--liquibase formatted sql

--changeset rlevasseur:v10-help-keyboard-content-0085 splitStatements:false
DO $outer$
BEGIN
  UPDATE content_cards SET body_html = $TODO$<p>The To-do app is where you keep track of everything you need to get done.</p><h3>Creating a list</h3><ol><li>Open the 📋 To-do app</li><li>Tap <strong>+ New List</strong></li><li>Tap the title to rename it</li><li>Start adding tasks</li></ol><h3>Adding tasks</h3><p>Type in the <strong>Add a to-do…</strong> input at the bottom of your list and tap <strong>Add</strong> (or press Enter).</p><h3>Checking things off</h3><p>Tap the checkbox next to a task. It feels good, trust us.</p><h3>Due dates</h3><p>Tap the 📅 icon next to a task to set a due date. Once set, the date appears as a small badge on the task — overdue dates are highlighted. Tap the badge to change or clear the date.</p><h3>Other things you can do</h3><ul><li><strong>Rename a list or task</strong> — tap the title or task text to edit it inline</li><li><strong>Delete a task</strong> — tap the <strong>✕</strong> button next to it (you'll be asked to confirm)</li><li><strong>Delete a list</strong> — tap the <strong>🗑</strong> icon (you'll be asked to confirm)</li><li><strong>Change the list color</strong> — tap the colored circle next to the list to pick a new color</li></ul><h3>Importing a How To list</h3><p>Some How To articles come with a ready-made to-do list. When you see one, tap <strong>"Add to My Locker"</strong> and a personal copy will appear in your To-do app — edit it however you want.</p><h3>Keyboard shortcuts</h3><ul><li><strong>↑ / ↓</strong> — move between lists or tasks</li><li><strong>Space</strong> — toggle a focused task complete / incomplete</li><li><strong>A</strong> or <strong>+</strong> — jump to the add-task input</li><li><strong>Enter</strong> — add a task (when typing in the add field)</li><li><strong>Tab</strong> — move focus between elements</li><li><strong>Escape</strong> — close any dialog or confirmation</li><li><strong>N</strong> — create a new list from anywhere in the To-do app</li><li><strong>1 / 2 / 3</strong> — switch between locker panes (works across all tools)</li></ul>$TODO$ WHERE slug = 'help-todo';

  UPDATE content_cards SET body_html = $NOTES$<p>Need to write something down fast? That's what Notes is for.</p><h3>Creating a note</h3><ol><li>Open the 📝 Notes app</li><li>Tap <strong>+ New Note</strong></li><li>Tap the title to rename it</li><li>Start typing</li></ol><p>Notes save automatically when you tap away or go back to the list — no save button to remember.</p><h3>What you can do with notes</h3><ul><li><strong>Pick a color</strong> — tap the color picker to color-code your notes so they're easy to spot</li><li><strong>Rename</strong> — tap the title to change it</li><li><strong>Delete</strong> — done with a note? Tap the delete button (you'll be asked to confirm)</li></ul><h3>Tips</h3><ul><li>Use notes for quick reminders, study summaries, or brain dumps before a test</li><li>Keep it short — if your note is turning into an essay, maybe it's time to open a doc instead</li></ul><h3>Keyboard shortcuts</h3><ul><li><strong>↑ / ↓</strong> — move between notes</li><li><strong>Space</strong> or <strong>Enter</strong> — open the focused note</li><li><strong>Tab</strong> — move between the title and content area when editing</li><li><strong>Escape</strong> — go back to the list or close a dialog</li><li><strong>N</strong> — create a new note from anywhere in the Notes app</li><li><strong>1 / 2 / 3</strong> — switch between locker panes (works across all tools)</li></ul>$NOTES$ WHERE slug = 'help-notes';

  UPDATE content_cards SET body_html = $TIMER$<p>One timer, two modes. Open the ⏱ Timer app and pick the mode that fits what you're doing using the tabs at the top.</p><h3>Basic Mode</h3><p>A simple countdown. Tap the time to set hours, minutes, and seconds, then hit <strong>Start</strong>. You'll hear a chime when it's done. Use <strong>Pause</strong> to stop the clock and <strong>Reset</strong> to start over.</p><p>Great for:</p><ul><li>Timed assignments</li><li>Quick breaks</li><li>"I'll study for 30 more minutes" situations</li></ul><h3>Pomodoro Mode</h3><p>The Pomodoro technique breaks your work into focused chunks:</p><ol><li><strong>Focus session</strong> (25 minutes by default)</li><li><strong>Short break</strong> (5 minutes by default)</li><li><strong>Repeat</strong></li><li>After a few focus sessions, take a longer break (15 minutes by default)</li></ol><p>The timer cycles through these phases automatically — just tap <strong>Start</strong> and you'll hear a chime at the end of each phase. Use <strong>Skip</strong> to jump to the next phase or <strong>Reset</strong> to start over.</p><p>The dots show how many focus sessions you've completed in the current cycle.</p><h3>Customizing Pomodoro</h3><p>Tap the <strong>⚙ gear icon</strong> in Pomodoro mode to adjust:</p><ul><li>Focus duration</li><li>Short break duration</li><li>Long break duration</li><li>How many focus sessions before the long break</li></ul><h3>Switching modes</h3><p>Tap the <strong>Basic</strong> or <strong>Pomodoro</strong> tab at the top. You can switch anytime the timer isn't running.</p><h3>Why Pomodoro works</h3><p>Your brain stays fresher when you take regular breaks. It's not about studying longer — it's about studying smarter.</p><h3>Keyboard shortcuts</h3><ul><li><strong>Enter</strong> — start the timer or save settings</li><li><strong>Escape</strong> — cancel editing or close the settings panel</li><li><strong>1 / 2 / 3</strong> — switch between locker panes (works across all tools)</li></ul>$TIMER$ WHERE slug = 'help-timer';

  UPDATE content_cards SET body_html = $PINS$<p>Pins are pinned web locations — URLs to websites you visit often, like your school portal, Google Classroom, Canvas, or anything else you need quick access to. They live in the 📌 Pins app <em>and</em> appear as quick-tap icons across the top of your locker home screen.</p><h3>How to add a Pin</h3><ol><li>Open the 📌 <strong>Pins</strong> app from your locker</li><li>Tap <strong>+ Add Pin</strong> at the bottom</li><li>Enter the URL (e.g. <code>https://classroom.google.com</code>)</li><li>Optionally enter a name so you know what it is at a glance</li><li>Tap <strong>Add</strong></li></ol><p>Your pin appears instantly in the list and on your home screen.</p><h3>Editing or deleting a Pin</h3><p>Each pin in the list has two action buttons:</p><ul><li><strong>✏ Edit</strong> — tap to update the URL or name</li><li><strong>✕ Delete</strong> — tap to remove the pin</li></ul><h3>Quick-adding from the home screen</h3><p>You can also tap the <strong>+</strong> button in the pins row on your home screen to add a new pin without opening the Pins app.</p><h3>Tips</h3><ul><li>Pin the sites you open every single day — saves searching or typing the URL</li><li>Give pins short, clear names so they're easy to recognise at a glance</li></ul><h3>Keyboard shortcuts</h3><ul><li><strong>↑ / ↓</strong> — move between pins</li><li><strong>Space</strong> — open the focused pin in a new tab</li><li><strong>Enter</strong> — confirm when adding or editing a pin</li><li><strong>Tab</strong> — move focus between fields when editing</li><li><strong>Escape</strong> — cancel or close any form</li><li><strong>N</strong> — add a new pin from anywhere in the Pins app</li><li><strong>1 / 2 / 3</strong> — switch between locker panes (works across all tools)</li></ul>$PINS$ WHERE slug = 'help-pins';
END;
$outer$;
--rollback DO $outer$
